function mapGraphToD3(apiResponse) {
  const nodes = apiResponse.nodes.map(n => {
    // 计算 maxOutDegree 用于归一化
    const maxOutDegree = Math.max(...apiResponse.nodes.map(x => x.outDegree || 0), 1);
    return {
      id: n.nodeId,
      shiPosition: Math.round((n.outDegree / maxOutDegree) * 10000),
      phase: new Date(n.timestamp * 1000).getMinutes() % 6, // ⚠️ 临时方案，真实phase需从PhaseTransition事件获取
      depth: n.edges?.[0]?.depth || 0,
      edgeCount: n.outDegree + n.inDegree,
      creator: n.creator,
      fourRights: n.fourRights
    };
  });

  const edges = [];
  apiResponse.nodes.forEach(n => {
    (n.edges || []).forEach(e => {
      edges.push({
        source: e.fromNode,
        target: e.toNode,
        edgeType: e.depth >= 3 ? 2 : e.depth >= 2 ? 1 : 0
      });
    });
  });

  return { nodes, edges };
}
```

**⚠️ 语义警告：**
- phase用timestamp取模是**临时方案**，真实phase必须从索引器的PhaseTransition事件获取
- edgeType从depth推导是**临时方案**，真实edgeType是合约里的uint8字段
